#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeNativePlatform: FfiConverter {
    fileprivate static let handleMap = UniffiHandleMap<NativePlatform>()

    typealias FfiType = UInt64
    typealias SwiftType = NativePlatform

    public static func lift(_ handle: UInt64) throws -> NativePlatform {
        if ((handle & 1) == 0) {
            // Rust-generated handle, construct a new class that uses the handle to implement the
            // interface
            return NativePlatformImpl(unsafeFromHandle: handle)
        } else {
            // Swift-generated handle, get the object from the handle map
            return try handleMap.remove(handle: handle)
        }
    }

    public static func lower(_ value: NativePlatform) -> UInt64 {
         if let rustImpl = value as? NativePlatformImpl {
             // Rust-implemented object.  Clone the handle and return it
            return rustImpl.uniffiCloneHandle()
         } else {
            // Swift object, generate a new vtable handle and return that.
            return handleMap.insert(obj: value)
         }
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> NativePlatform {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: NativePlatform, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeNativePlatform_lift(_ handle: UInt64) throws -> NativePlatform {
    return try FfiConverterTypeNativePlatform.lift(handle)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeNativePlatform_lower(_ value: NativePlatform) -> UInt64 {
    return FfiConverterTypeNativePlatform.lower(value)
}






public protocol OctaPassVaultProtocol: AnyObject, Sendable {
    
    /**
     * The keys the SSH agent offers, by title. Fails with `locked` while locked.
     */
    func sshAgentKeys() async throws  -> [SshAgentKey]
    
    /**
     * Serves the browser extension (plan 13) on `native-host.sock` in `data_dir` (the App Group
     * container), answering only `host_path`, the `octapass-native-host` in the app's bundle,
     * started by a known browser; in a release build only when it's signed by the app's own
     * team. `development` also answers the development extension: true in the app's debug
     * builds only. Works while locked: the extension can ask to unlock with Touch ID.
     */
    func startBrowserBridge(dataDir: String, hostPath: String, development: Bool) throws  -> DesktopService
    
    /**
     * Serves the `octapass` CLI (plan 05) on `cli.sock` in `data_dir`: the CLI uses this app's
     * account and is unlocked while the app is, with no prompt; while locked, a request asks
     * Touch ID or the Mac's password. A CLI that isn't signed in is linked to the account.
     */
    func startCliSession(dataDir: String) throws  -> DesktopService
    
    /**
     * Starts the SSH agent (plans 05 and 16) on `endpoint`: the vault's SSH keys, a signature
     * asking Touch ID or the Mac's password (or `prompts.approve` on a Mac with neither) once per 15
     * minutes per unlock. A request while locked asks to unlock. `None` is `~/.octapass/agent.sock`, which
     * the sandboxed app can't make: the Mac app passes `agent.sock` in its App Group container.
     */
    func startSshAgent(prompts: SshPromptsCallback, endpoint: String?) throws  -> SshAgentHandle
    
    /**
     * Whether the AutoFill extension or the Autofill services can fill without a prompt right
     * now because of the autofill gate (not stay unlocked): the fill key is on this phone.
     */
    func fillsWithoutPrompt()  -> Bool
    
    /**
     * "Use on this device only": a new vault with no account, unlocked and current. Runs
     * Argon2id twice. Returns the backup recovery code, for the local Recovery Kit.
     */
    func createLocalVault(name: String, password: String) async throws  -> String
    
    /**
     * Deletes the open vault from this phone for good, after the master password. Backups
     * stay where they are. Another local vault becomes current, if there is one.
     */
    func deleteLocalVault(password: String) async throws 
    
    /**
     * A backup of the open vault in the app's private storage, for the share sheet or the
     * save dialog. `closeAttachment(path)` deletes it afterwards. Call `localBackupSaved` when
     * the user really saved it: cancelling doesn't count.
     */
    func exportLocalBackup() async throws  -> String
    
    /**
     * **Turn on sync**, second half: the items move into the new account as they are and the
     * local vault is removed. Show the Recovery Kit next. A wrong code can be tried again.
     */
    func finishTurnOnSync(signupId: String, verificationCode: String) async throws  -> RecoveryKit
    
    /**
     * Back to the first screen, to add a vault or sign in. Nothing is deleted, and the vault
     * stays in `localVaults`.
     */
    func leaveLocalVault() async throws 
    
    /**
     * The file from `exportLocalBackup` reached where the user chose.
     */
    func localBackupSaved() async throws 
    
    /**
     * Fast: call it anywhere.
     */
    func localCapabilities()  -> LocalCapabilities
    
    /**
     * The open vault's backup recovery code. Ask for the device lock or the master password
     * first (`confirmUser`).
     */
    func localRecoveryCode() async throws  -> String
    
    /**
     * Every vault on this phone only. Fast: call it anywhere, signed out too.
     */
    func localVaults()  -> [LocalVaultInfo]
    
    func renameLocalVault(name: String) async throws 
    
    /**
     * Restores a `.octapass-backup` file as a new vault here, unlocked and current. Fails with
     * `invalidBackup` when the file is damaged or the password or code doesn't open it.
     */
    func restoreLocalVault(path: String, key: BackupKey) async throws 
    
    /**
     * Turns automatic backups on for the open vault, into `folder` (the platform's reference)
