    func createFile(folder: String, name: String) throws  -> SafeEntry
    
    func createFolder(folder: String, name: String) throws  -> SafeEntry
    
    func entry(id: String) throws  -> SafeEntry
    
    /**
     * Decrypts a file to `path`. The caller owns that plaintext and removes it when it's done.
     */
    func exportFile(id: String, path: String) async throws  -> UInt64
    
    /**
     * Seals what was written to a file as a new revision. Locking does this too.
     */
    func flush(id: String) throws 
    
    /**
     * Replaces a file's contents with those of the file at `path`, as one new revision.
     */
    func importFile(id: String, path: String) async throws  -> UInt64
    
    func isLocked()  -> Bool
    
    func list(folder: String) throws  -> [SafeEntry]
    
    /**
