     */
    func read(id: String, offset: UInt64, size: UInt32) throws  -> Data
    
    /**
     * Deletes a file, or a folder and everything in it.
     */
    func remove(id: String) throws 
    
    func rename(id: String, folder: String, name: String) throws 
    
    /**
     * Cuts or extends a file to `size`, in staging like `write`.
     */
    func truncate(id: String, size: UInt64) throws 
    
    func warnings() throws  -> [SafeWarning]
    
    /**
     * Changes part of a file. What's written waits in the engine's staging file, sealed under a
     * throwaway key, so no plaintext reaches the disk. `flush` makes it a new revision.
     */
    func write(id: String, offset: UInt64, data: Data) throws 
    
