/**
 * What another password manager handed over (Android's credential transfer, iOS's Credential
 * Exchange), for the user to look at before anything is saved. No secrets.
 */
public struct ReceivedPreview: Equatable, Hashable {
    /**
     * The app's name.
     */
    public var from: String
    /**
     * New items by type, in type name order.
     */
    public var items: [ReceivedCount]
    /**
     * Passkeys among the new items.
     */
    public var passkeys: UInt32
    /**
     * One-time codes that join logins already in the vault.
     */
    public var codes: UInt32
    /**
     * Items already in the Personal vault that this changes.
     */
    public var updated: UInt32
    /**
     * Items already there exactly as sent.
     */
    public var unchanged: UInt32
    public var skipped: UInt32
    public var warnings: [String]

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * The app's name.
         */from: String, 
        /**
         * New items by type, in type name order.
         */items: [ReceivedCount], 
        /**
         * Passkeys among the new items.
         */passkeys: UInt32, 
        /**
         * One-time codes that join logins already in the vault.
         */codes: UInt32, 
        /**
         * Items already in the Personal vault that this changes.
         */updated: UInt32, 
        /**
         * Items already there exactly as sent.
         */unchanged: UInt32, skipped: UInt32, warnings: [String]) {
        self.from = from
        self.items = items
        self.passkeys = passkeys
        self.codes = codes
        self.updated = updated
        self.unchanged = unchanged
        self.skipped = skipped
        self.warnings = warnings
    }

    

    
}

