/**
 * The web vault's settings (`apps/web/src/app/settings.tsx`) plus the list order.
 */
public struct Settings: Equatable, Hashable {
    public var theme: ThemePreference
    public var language: LanguagePreference
    /**
     * Minutes of inactivity before the vault locks: 1, 5, 15, 30, 60 or 240; 0 locks only when
     * the app is closed.
     */
    public var autoLockMinutes: UInt32
    /**
     * Lock as soon as the app goes to the background.
     */
    public var lockOnBackground: Bool
    public var listSort: ListSort
    public var listGrouping: ListGrouping
    /**
     * Each list's own sort and grouping, by view (`listArrangement` / `setListArrangement`).
     */
    public var listArrangements: [String: ListArrangement]
    /**
     * Lists show two or more logins for the same website as one row.
     */
    public var combineSites: Bool
    /**
     * Website icons through the user's server (plan 04). Off means no requests, and clears the
     * icons kept on this phone.
     */
    public var showSiteIcons: Bool
    /**
     * Offer to save a network the phone joins that isn't in the vault.
     */
    public var wifiOffers: Bool
    /**
     * Send one-time codes to a paired watch while the vault is unlocked (`watchPayload`). This
     * phone's choice, never synced.
     */
    public var showCodesOnWatch: Bool
    /**
     * The app-open gate (plan 03, per device, never synced): opening the app asks for the
     * device lock where it's set up. Off: the master password instead.
     */
    public var deviceAuthOnOpen: Bool
    /**
     * The autofill gate (plan 03, per device, never synced): the AutoFill extension or the
     * Autofill services ask for the device lock on every fill. Off: they fill directly while the
     * app's vault is unlocked (`fill_gate`). Applies only with stay unlocked off.
     */
    public var deviceAuthOnAutofill: Bool
    /**
     * Stay unlocked while logged in to this phone (plan 18, per device, never synced): the app
     * opens without a prompt while the phone is unlocked, with no lock timer and no lock in the
     * background; filling doesn't ask. Needs a passcode; without one the phone locks as before.
     * On for new installs; see [`load_settings`] for existing ones.
     */
    public var stayUnlocked: Bool

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(theme: ThemePreference, language: LanguagePreference, 
        /**
         * Minutes of inactivity before the vault locks: 1, 5, 15, 30, 60 or 240; 0 locks only when
         * the app is closed.
         */autoLockMinutes: UInt32, 
        /**
         * Lock as soon as the app goes to the background.
         */lockOnBackground: Bool, listSort: ListSort, listGrouping: ListGrouping, 
        /**
         * Each list's own sort and grouping, by view (`listArrangement` / `setListArrangement`).
         */listArrangements: [String: ListArrangement] = [:], 
        /**
         * Lists show two or more logins for the same website as one row.
         */combineSites: Bool = true, 
        /**
         * Website icons through the user's server (plan 04). Off means no requests, and clears the
         * icons kept on this phone.
         */showSiteIcons: Bool = true, 
        /**
         * Offer to save a network the phone joins that isn't in the vault.
         */wifiOffers: Bool = true, 
        /**
         * Send one-time codes to a paired watch while the vault is unlocked (`watchPayload`). This
         * phone's choice, never synced.
         */showCodesOnWatch: Bool = false, 
        /**
         * The app-open gate (plan 03, per device, never synced): opening the app asks for the
         * device lock where it's set up. Off: the master password instead.
         */deviceAuthOnOpen: Bool = true, 
        /**
         * The autofill gate (plan 03, per device, never synced): the AutoFill extension or the
         * Autofill services ask for the device lock on every fill. Off: they fill directly while the
         * app's vault is unlocked (`fill_gate`). Applies only with stay unlocked off.
         */deviceAuthOnAutofill: Bool = true, 
        /**
         * Stay unlocked while logged in to this phone (plan 18, per device, never synced): the app
         * opens without a prompt while the phone is unlocked, with no lock timer and no lock in the
         * background; filling doesn't ask. Needs a passcode; without one the phone locks as before.
         * On for new installs; see [`load_settings`] for existing ones.
         */stayUnlocked: Bool = true) {
        self.theme = theme
        self.language = language
        self.autoLockMinutes = autoLockMinutes
        self.lockOnBackground = lockOnBackground
        self.listSort = listSort
        self.listGrouping = listGrouping
        self.listArrangements = listArrangements
        self.combineSites = combineSites
        self.showSiteIcons = showSiteIcons
        self.wifiOffers = wifiOffers
        self.showCodesOnWatch = showCodesOnWatch
        self.deviceAuthOnOpen = deviceAuthOnOpen
        self.deviceAuthOnAutofill = deviceAuthOnAutofill
        self.stayUnlocked = stayUnlocked
    }

    

    
}

