     */
    case resetExpired
    /**
     * The recovery code doesn't open this account.
     */
    case invalidRecoveryCode
    case signupsClosed
    case insecureServerUrl
    case serverUnreachable
    case serverError
    case rateLimited
    case sessionExpired
    case accountDeleted
    case reauthRequired
    case locked
    case notFound
    case readOnlyVault
    case invalidImportFile
    case importPasswordRequired
    case wrongImportPassword
    case emailMismatch
    case deviceUnlockUnsupported
    case deviceUnlockCancelled
    case deviceUnlockFailed
    case passwordRequired
    case accountNotFound
    case notAllowed
    case alreadyExists
    case familyFull
    case quotaExceeded
    case untrustedVault
    case wrongPassphrase
    /**
     * A protected SSH key: ask for its passphrase and read it again.
     */
    case sshPassphraseRequired
    case invalidSshKey
    case unsupportedSshKey
    /**
     * A `.pub` file where a private key was expected.
     */
    case sshPublicKeyOnly
    case invalidShareLink
    case fileTooLarge
    case invalidTwoStepCode
    case twoStepExpired
    /**
     * The identity provider hasn't finished in the browser yet.
     */
    case ssoPending
