/**
 * The web vault's generator settings.
 */

public enum GeneratorOptions: Equatable, Hashable {
    
    /**
     * 4–128 characters from the chosen sets, at least one of each.
     */
    case password(length: UInt32, uppercase: Bool, lowercase: Bool, digits: Bool, symbols: Bool, 
        /**
         * Leaves out look-alikes such as `0 O 1 l I`.
         */avoidAmbiguous: Bool
    )
    /**
     * 3–20 words from the EFF large wordlist.
     */
    case passphrase(words: UInt32, separator: String, capitalize: Bool, includeNumber: Bool
    )





}

#if compiler(>=6)
extension GeneratorOptions: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeGeneratorOptions: FfiConverterRustBuffer {
    typealias SwiftType = GeneratorOptions

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> GeneratorOptions {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .password(length: try FfiConverterUInt32.read(from: &buf), uppercase: try FfiConverterBool.read(from: &buf), lowercase: try FfiConverterBool.read(from: &buf), digits: try FfiConverterBool.read(from: &buf), symbols: try FfiConverterBool.read(from: &buf), avoidAmbiguous: try FfiConverterBool.read(from: &buf)
        )
        
        case 2: return .passphrase(words: try FfiConverterUInt32.read(from: &buf), separator: try FfiConverterString.read(from: &buf), capitalize: try FfiConverterBool.read(from: &buf), includeNumber: try FfiConverterBool.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: GeneratorOptions, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .password(length,uppercase,lowercase,digits,symbols,avoidAmbiguous):
            writeInt(&buf, Int32(1))
            FfiConverterUInt32.write(length, into: &buf)
            FfiConverterBool.write(uppercase, into: &buf)
            FfiConverterBool.write(lowercase, into: &buf)
            FfiConverterBool.write(digits, into: &buf)
            FfiConverterBool.write(symbols, into: &buf)
            FfiConverterBool.write(avoidAmbiguous, into: &buf)
            
        
        case let .passphrase(words,separator,capitalize,includeNumber):
            writeInt(&buf, Int32(2))
            FfiConverterUInt32.write(words, into: &buf)
            FfiConverterString.write(separator, into: &buf)
            FfiConverterBool.write(capitalize, into: &buf)
            FfiConverterBool.write(includeNumber, into: &buf)
            
        }
    }
}


